const signups = $input.all().map(i => i.json);
const shifts = $('Lookup Shift').all().map(i => i.json);
const norm = $('Normalize Signup').item.json;
const shiftId = String(norm.shift_id || '').trim();
const shift = shifts.find(s => String(s.shift_id || '').trim() === shiftId) || null;
const count = signups.filter(s => String(s.shift_id || '').trim() === shiftId).length;
const capacity = shift ? Number(shift.capacity) || 0 : 0;
const is_full = shift ? count >= capacity : false;
return [{
  json: {
    ...norm,
    found: !!shift,
    is_full,
    signup_count: count,
    capacity,
    shift_role: shift ? shift.role : '',
    shift_date: shift ? shift.date : '',
    shift_start: shift ? shift.start_time : '',
    shift_end: shift ? shift.end_time : '',
    shift_location: shift ? shift.location : '',
    shift_description: shift ? shift.description : '',
  }
}];

const signups = $input.all().map(i => i.json);
const now = new Date();
const jkt = new Date(now.getTime() + 7 * 3600 * 1000);
const fmt = d => d.getUTCFullYear() + '-' + String(d.getUTCMonth() + 1).padStart(2, '0') + '-' + String(d.getUTCDate()).padStart(2, '0');
const todayStr = fmt(jkt);
const tomorrow = new Date(jkt.getTime() + 24 * 3600 * 1000);
const tomorrowStr = fmt(tomorrow);
const upcoming = signups
  .filter(s => String(s.status || '') === 'confirmed')
  .filter(s => String(s.shift_date || '') === todayStr || String(s.shift_date || '') === tomorrowStr)
  .map(s => ({ full_name: s.full_name, email: s.email, shift_role: s.shift_role, shift_date: s.shift_date, shift_start: s.shift_start, shift_end: s.shift_end, shift_location: s.shift_location }));
return [{ json: { reminder_count: upcoming.length, reminders: upcoming } }];

const signups = $input.all().map(i => i.json);
const shifts = $('Read Shifts for Digest').all().map(i => i.json);
const now = new Date();
const jkt = new Date(now.getTime() + 7 * 3600 * 1000);
const fmt = d => d.getUTCFullYear() + '-' + String(d.getUTCMonth() + 1).padStart(2, '0') + '-' + String(d.getUTCDate()).padStart(2, '0');
const todayStr = fmt(jkt);
const weekAgo = new Date(jkt.getTime() - 7 * 24 * 3600 * 1000);
const weekAgoStr = fmt(weekAgo);
const week = signups.filter(s => {
  const d = String(s.received_at || '').slice(0, 10);
  return d >= weekAgoStr && d <= todayStr;
});
const confirmed = week.filter(s => String(s.status || '') === 'confirmed');
const waitlisted = week.filter(s => String(s.status || '') === 'waitlist');
let totalHours = 0;
for (const s of confirmed) {
  const st = String(s.shift_start || '').split(':').map(Number);
  const en = String(s.shift_end || '').split(':').map(Number);
  if (st.length >= 2 && en.length >= 2 && !isNaN(st[0]) && !isNaN(en[0])) {
    totalHours += Math.max(0, (en[0] * 60 + (en[1] || 0)) - (st[0] * 60 + (st[1] || 0))) / 60;
  }
}
const openShifts = shifts.filter(sh => {
  const count = signups.filter(s => String(s.shift_id || '') === String(sh.shift_id || '') && String(s.status || '') === 'confirmed').length;
  return count < (Number(sh.capacity) || 0);
}).map(sh => sh.role);
return [{ json: {
  total_signups: week.length,
  confirmed: confirmed.length,
  waitlisted: waitlisted.length,
  total_hours: Math.round(totalHours * 10) / 10,
  open_shifts: openShifts,
  week_start: weekAgoStr,
  week_end: todayStr
} }];

